// Checks the request and the workflow settings before anything touches ClickUp.
// Dates are calendar dates (YYYY-MM-DD) in the business time zone (TIMEZONE).
const TZ = $env.TIMEZONE || 'America/New_York';
const event = $('Webhook: Amendment').isExecuted ? 'amendment' : 'under_contract';
const raw = $json.body;
const body = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
const errors = [];
const config = [];
const warnings = [];

const isDate = (v) => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && DateTime.fromISO(v, { zone: TZ }).isValid;
const isEmail = (v) => typeof v === 'string' && /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(v.trim());
const text = (v, max) => (typeof v === 'string' && v.trim() && v.trim().length <= max ? v.trim().replace(/\s+/g, ' ') : '');
const PRIORITY = { urgent: 1, high: 2, normal: 3, low: 4 };
const STANDARD = { inspection: 'inspection_days', appraisal: 'appraisal_days', financing: 'financing_days' };

function days(value, label, min) {
  if (value === undefined || value === null || value === '') return null;
  const n = typeof value === 'string' && /^\s*\d+\s*$/.test(value) ? Number(value) : value;
  if (!Number.isInteger(n) || n < min || n > 365) {
    errors.push(`${label} must be a whole number from ${min} to 365`);
    return null;
  }
  return n;
}

function customMilestones(list) {
  if (list === undefined || list === null) return [];
  if (!Array.isArray(list)) { errors.push('custom_milestones must be a list'); return []; }
  if (list.length > 20) { errors.push('custom_milestones can have at most 20 entries'); return []; }
  const seen = new Set();
  const out = [];
  list.forEach((m, i) => {
    const name = text(m && m.name, 100);
    if (!name) { errors.push(`custom_milestones[${i}].name is required (up to 100 characters)`); return; }
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    if (!slug) { errors.push(`custom_milestones[${i}].name needs at least one letter or number`); return; }
    const key = 'custom:' + slug;
    if (seen.has(key)) { errors.push(`custom_milestones[${i}].name "${name}" is listed twice`); return; }
    seen.add(key);
    const d = days(m.days, `custom_milestones[${i}].days`, 0);
    if (d === null) { if (m.days === undefined || m.days === null || m.days === '') errors.push(`custom_milestones[${i}].days is required`); return; }
    let priority = 3;
    if (m.priority !== undefined && m.priority !== null && m.priority !== '') {
      priority = PRIORITY[String(m.priority).trim().toLowerCase()];
      if (!priority) { errors.push(`custom_milestones[${i}].priority must be urgent, high, normal or low`); return; }
    }
    out.push({ key, name, days: d, priority });
  });
  return out;
}

// Settings
const required = {
  CLICKUP_API_TOKEN: $env.CLICKUP_API_TOKEN,
  CLICKUP_LIST_ID: $env.CLICKUP_LIST_ID,
  CLICKUP_DEAL_ID_FIELD_ID: $env.CLICKUP_DEAL_ID_FIELD_ID,
  CLICKUP_MILESTONE_FIELD_ID: $env.CLICKUP_MILESTONE_FIELD_ID,
};
for (const [name, value] of Object.entries(required)) if (!value) config.push(`${name} is not set`);
if (!DateTime.now().setZone(TZ).isValid) config.push(`TIMEZONE "${TZ}" is not a valid IANA time zone, for example America/Chicago`);
const dueTime = $env.DEADLINE_TIME || '17:00';
if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(dueTime)) config.push(`DEADLINE_TIME "${dueTime}" must be a 24 hour time like 17:00`);
String($env.HOLIDAYS || '').split(',').map((s) => s.trim()).filter(Boolean)
  .forEach((h) => { if (!isDate(h)) config.push(`HOLIDAYS entry "${h}" is not a YYYY-MM-DD date`); });
let team = [];
try {
  team = JSON.parse($env.TEAM_MEMBERS || '[]');
  if (!Array.isArray(team) || team.some((m) => !m || !isEmail(m.email) || !Number.isInteger(Number(m.clickup_id)))) throw new Error('bad');
} catch (e) {
  config.push('TEAM_MEMBERS must be a JSON list of people, each with an email and a numeric clickup_id');
  team = [];
}
const findMember = (email) => team.find((m) => String(m.email).trim().toLowerCase() === String(email || '').trim().toLowerCase());

// Request
const dealId = (typeof body.deal_id === 'string' || typeof body.deal_id === 'number') ? String(body.deal_id).trim() : '';
if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(dealId)) errors.push('deal_id is required: letters, numbers, dots, dashes or underscores, up to 64 characters');
let roll = null;
if (body.roll_to_business_day !== undefined) {
  if (typeof body.roll_to_business_day !== 'boolean') errors.push('roll_to_business_day must be true or false');
  else roll = body.roll_to_business_day;
}
const periods = {};
let request;

if (event === 'under_contract') {
  const address = text(body.property_address, 200);
  if (!address) errors.push('property_address is required (up to 200 characters)');
  const side = String(body.side || '').trim().toLowerCase();
  if (!['buyer', 'seller', 'dual'].includes(side)) errors.push('side must be buyer, seller or dual');
  if (!isDate(body.contract_date)) errors.push('contract_date must be a real date in YYYY-MM-DD format');
  if (!isDate(body.closing_date)) errors.push('closing_date must be a real date in YYYY-MM-DD format');
  else if (isDate(body.contract_date) && body.closing_date <= body.contract_date) errors.push('closing_date must be after contract_date');
  for (const [key, field] of Object.entries(STANDARD)) periods[key] = days(body[field], field, 0);
  const custom = customMilestones(body.custom_milestones);
  if (!isEmail(body.agent_email)) errors.push('agent_email is required');

  // Agent and transaction coordinator come from TEAM_MEMBERS, so the CRM never needs ClickUp user IDs.
  const agent = findMember(body.agent_email);
  const tcEmail = isEmail(body.tc_email) ? body.tc_email : ($env.TC_EMAIL || '');
  const tc = tcEmail ? findMember(tcEmail) : null;
  if (tcEmail && !tc) config.push(`The transaction coordinator ${tcEmail} is not in TEAM_MEMBERS`);
  if (isEmail(body.agent_email) && !agent) warnings.push(`Agent ${String(body.agent_email).trim()} is not in TEAM_MEMBERS, so the tasks are assigned to the transaction coordinator only`);
  const assignees = [...new Set([agent, tc].filter(Boolean).map((m) => Number(m.clickup_id)))];
  if (!assignees.length) warnings.push('Nobody could be assigned: add the agent to TEAM_MEMBERS or set TC_EMAIL');
  request = {
    address, side, contractDate: body.contract_date, closingDate: body.closing_date, periods, custom, roll,
    agentName: agent ? agent.name || agent.email : String(body.agent_email || '').trim(),
    tcName: tc ? tc.name || tc.email : '', assignees,
  };
} else {
  if (body.contract_date !== undefined) errors.push('contract_date cannot be changed by an amendment. Every deadline counts from it, so delete the deal task in ClickUp and send the under contract webhook again');
  let closingDate = null;
  if (body.new_closing_date !== undefined) {
    if (!isDate(body.new_closing_date)) errors.push('new_closing_date must be a real date in YYYY-MM-DD format');
    else closingDate = body.new_closing_date;
  }
  // Amendments carry the new total period, not the difference, so a repeated delivery changes nothing.
  for (const [key, field] of Object.entries(STANDARD)) periods[key] = days(body[field], field, 1);
  const custom = customMilestones(body.custom_milestones);
  const changes = (closingDate ? 1 : 0) + Object.values(periods).filter((v) => v !== null).length + custom.length;
  if (!changes && !errors.length) errors.push('Nothing to change: send new_closing_date, inspection_days, appraisal_days, financing_days or custom_milestones');
  const amendmentId = body.amendment_id === undefined ? '' : text(String(body.amendment_id), 64);
  if (body.amendment_id !== undefined && !amendmentId) errors.push('amendment_id must be up to 64 characters');
  const note = body.note === undefined ? '' : text(body.note, 500);
  if (body.note !== undefined && !note) errors.push('note must be text up to 500 characters');
  request = { closingDate, periods, custom, roll, amendmentId, note };
}

const ok = errors.length === 0 && config.length === 0;
return [{
  json: {
    ok,
    event,
    dealId,
    httpStatus: config.length ? 500 : 400,
    errors: config.length ? config.map((c) => 'Workflow setting: ' + c) : errors,
    warnings,
    request: ok ? request : null,
  },
}];

// Works out every deadline and compares it with what ClickUp already holds for this deal.
// ClickUp is the record: the deal task and each milestone subtask carry the Deal ID custom field,
// and each subtask carries its Milestone key, so a repeated webhook finds them instead of duplicating them.
const v = $('Validate Deal').first().json;
const r = v.request;
const TZ = $env.TIMEZONE || 'America/New_York';
const DUE_TIME = $env.DEADLINE_TIME || '17:00';
const ROLL_DEFAULT = String($env.ROLL_TO_BUSINESS_DAY || 'true').trim().toLowerCase() !== 'false';
const HOLIDAYS = new Set(String($env.HOLIDAYS || '').split(',').map((s) => s.trim()).filter(Boolean));
const DEAL_FIELD = $env.CLICKUP_DEAL_ID_FIELD_ID;
const KEY_FIELD = $env.CLICKUP_MILESTONE_FIELD_ID;
const roll = r.roll === null ? ROLL_DEFAULT : r.roll;
const NAMES = { inspection: 'Inspection contingency ends', appraisal: 'Appraisal contingency ends', financing: 'Financing contingency ends', closing: 'Closing' };
const ORDER = ['inspection', 'appraisal', 'financing'];

const day = (iso) => DateTime.fromISO(iso, { zone: TZ }).startOf('day');
const short = (d) => d.toFormat('ccc LLL d, yyyy');
const stamp = (ms) => DateTime.fromMillis(Number(ms), { zone: TZ }).toFormat('ccc LLL d, yyyy h:mm a ZZZZ');
const md = (s) => String(s).replace(/([\\`*_\[\]<>|#])/g, '\\$1');
const isBusinessDay = (d) => d.weekday <= 5 && !HOLIDAYS.has(d.toISODate());

// Calendar days from the base date. A deadline on a weekend or holiday moves to the next business day.
function deadline(base, add) {
  const target = base.plus({ days: add });
  let date = target;
  if (roll) while (!isBusinessDay(date)) date = date.plus({ days: 1 });
  const due = DateTime.fromISO(`${date.toISODate()}T${DUE_TIME}`, { zone: TZ });
  const moved = date.toISODate() !== target.toISODate();
  return {
    date: date.toISODate(),
    dueMs: due.toMillis(),
    dueIso: due.toISO({ suppressMilliseconds: true }),
    dueLabel: stamp(due.toMillis()),
    rolledFrom: moved ? target.toISODate() : null,
    rollNote: moved ? `${short(target)} is a ${target.weekday > 5 ? 'weekend day' : 'holiday'}, so the deadline moves to the next business day.` : '',
  };
}

const describe = (m, dealLine, extra) => [`**Deal:** ${dealLine}`, `**Deadline:** ${m.dueLabel}`, `**Rule:** ${m.rule}`, m.rollNote, extra]
  .filter(Boolean).join('\n\n');

const fieldValue = (t, id) => {
  const f = (t.custom_fields || []).find((x) => x.id === id);
  return f && f.value !== undefined && f.value !== null ? String(f.value) : '';
};
// One item per page of results. Reading every page matters: a missed page would look like missing milestones.
const all = $input.all().flatMap((i) => (Array.isArray(i.json.tasks) ? i.json.tasks : []));
const mine = all.filter((t) => fieldValue(t, DEAL_FIELD) === v.dealId);
const parents = mine.filter((t) => !t.parent).sort((a, b) => Number(a.date_created) - Number(b.date_created));
const parent = parents[0] || null;
const warnings = [...v.warnings];
if (parents.length > 1) warnings.push(`${parents.length} deal tasks in ClickUp carry deal ID ${v.dealId}. The oldest one (${parent.id}) is used; please delete the others.`);
const existing = {};
if (parent) {
  for (const t of mine) {
    const k = fieldValue(t, KEY_FIELD);
    if (t.parent === parent.id && k && !existing[k]) existing[k] = t;
  }
}
const parentInfo = parent ? { id: parent.id, name: parent.name, url: parent.url } : null;
const createBody = (m, dealLine, assignees) => ({
  name: m.name,
  markdown_content: describe(m, dealLine),
  assignees,
  priority: m.priority,
  due_date: m.dueMs,
  due_date_time: true,
  custom_fields: [{ id: DEAL_FIELD, value: v.dealId }, { id: KEY_FIELD, value: m.key }],
});
const afterClosing = (list, closingMs) => list.filter((m) => m.key !== 'closing' && m.dueMs > closingMs)
  .map((m) => `${m.name} (${m.dueLabel}) is after closing (${stamp(closingMs)}). Check the contract.`);
// The deal task's start date holds the contract date (set at local noon, so a shift of a few hours keeps the date).
const storedContract = parent && parent.start_date ? DateTime.fromMillis(Number(parent.start_date), { zone: TZ }).startOf('day') : null;
const reject = (status, httpStatus, errorMessage, extra) => ({
  route: 'reject', status, httpStatus, errorMessage,
  response: { ok: false, status, deal_id: v.dealId, ...(parentInfo ? { task_id: parentInfo.id, task_url: parentInfo.url } : {}), error: errorMessage, ...extra },
});

let out;
if (v.event === 'under_contract' && storedContract && storedContract.toISODate() !== r.contractDate) {
  // Every deadline counts from the contract date. Mixing two contract dates in one deal would leave some
  // deadlines wrong without anyone noticing, so nothing is written and the run raises an alert.
  out = reject('conflict', 409,
    `Deal ${v.dealId} is already in ClickUp with contract date ${storedContract.toISODate()}, but this request says ${r.contractDate}. `
    + 'Nothing was changed. If the contract date really changed, delete the deal task and its subtasks in ClickUp and send the webhook again.');
} else if (v.event === 'under_contract') {
  const contract = day(r.contractDate);
  const ms = [];
  ORDER.forEach((k) => {
    const n = r.periods[k];
    if (n) ms.push({ key: k, name: NAMES[k], priority: 2, ...deadline(contract, n), rule: `Contract date (${short(contract)}) + ${n} days` });
  });
  r.custom.forEach((c) => ms.push({ key: c.key, name: c.name, priority: c.priority, ...deadline(contract, c.days), rule: `Contract date (${short(contract)}) + ${c.days} days` }));
  const closing = { key: 'closing', name: NAMES.closing, priority: 1, ...deadline(day(r.closingDate), 0), rule: `Closing date in the contract (${short(day(r.closingDate))})` };
  ms.push(closing);
  ms.sort((a, b) => a.dueMs - b.dueMs);
  warnings.push(...afterClosing(ms, closing.dueMs));

  const dealLine = `${v.dealId}, ${md(r.address)}`;
  const ops = ms.filter((m) => !existing[m.key]).map((m) => ({
    op: 'create', key: m.key, name: m.name, dueMs: m.dueMs, dueLabel: m.dueLabel, body: createBody(m, dealLine, r.assignees),
  }));
  const differ = ms.filter((m) => existing[m.key] && Number(existing[m.key].due_date) !== m.dueMs).map((m) => m.name);
  if (parent && differ.length) warnings.push(`This deal was already in ClickUp. These dates differ from the existing tasks and were not changed: ${differ.join(', ')}. Send an amendment to change them.`);
  const side = { buyer: 'Buyer side', seller: 'Seller side', dual: 'Both sides (dual agency)' }[r.side];
  const contractNoon = DateTime.fromISO(`${r.contractDate}T12:00`, { zone: TZ }).toMillis();
  const parentBody = {
    name: r.address,
    markdown_content: [
      `- **Deal ID:** ${v.dealId}`,
      `- **Side:** ${side}`,
      `- **Agent:** ${md(r.agentName)}`,
      ...(r.tcName ? [`- **Transaction coordinator:** ${md(r.tcName)}`] : []),
      `- **Contract date:** ${short(contract)}`,
      `- **Closing:** ${closing.dueLabel}`,
    ].join('\n') + '\n\nEach deadline is a subtask of this task. Amendments move them and leave a comment here.\n\n'
      + 'The start date of this task holds the contract date that amendments count from, so please leave it as it is.',
    assignees: r.assignees,
    start_date: contractNoon,
    start_date_time: false,
    due_date: closing.dueMs,
    due_date_time: true,
    custom_fields: [{ id: DEAL_FIELD, value: v.dealId }],
  };
  const milestones = ms.map((m) => ({
    key: m.key, name: m.name, due: m.dueIso, due_label: m.dueLabel, rolled_from: m.rolledFrom,
    task_id: existing[m.key] ? existing[m.key].id : null, task_url: existing[m.key] ? existing[m.key].url : null,
  }));
  const route = !parent ? 'create_parent' : ops.length ? 'write' : 'unchanged';
  out = {
    route, status: { create_parent: 'created', write: 'repaired', unchanged: 'unchanged' }[route],
    parent: parentInfo, parentBody: parent ? null : parentBody, ops, milestones, warnings,
  };
  if (route === 'unchanged') {
    out.httpStatus = 200;
    out.response = {
      ok: true, status: 'unchanged', deal_id: v.dealId, task_id: parent.id, task_url: parent.url, milestones, warnings,
      message: 'This deal is already in ClickUp with every milestone, so nothing was created. Send an amendment to change dates.',
    };
  }
} else if (!parent) {
  out = reject('not_found', 404,
    `Amendment for deal ${v.dealId} was rejected because no deal task in ClickUp has that deal ID. Send the under contract webhook first.`);
} else if (!storedContract) {
  out = reject('no_contract_date', 409,
    `Amendment for deal ${v.dealId} was rejected because the deal task has no start date, so the contract date is unknown. Set the start date back to the contract date and resend.`);
} else if (r.closingDate && r.closingDate <= storedContract.toISODate()) {
  out = reject('invalid', 400,
    `Amendment for deal ${v.dealId} was rejected because new_closing_date ${r.closingDate} is not after the contract date ${storedContract.toISODate()}. Nothing was changed.`,
    { errors: [`new_closing_date must be after the contract date (${storedContract.toISODate()})`] });
} else {
  const contract = storedContract;
  const label = r.amendmentId ? `amendment ${r.amendmentId}` : 'an amendment';
  const targets = [];
  ORDER.forEach((k) => {
    const n = r.periods[k];
    if (n !== null) targets.push({ key: k, name: existing[k] ? existing[k].name : NAMES[k], priority: 2, ...deadline(contract, n), rule: `Contract date (${short(contract)}) + ${n} days, set by ${label}` });
  });
  r.custom.forEach((c) => targets.push({ key: c.key, name: existing[c.key] ? existing[c.key].name : c.name, priority: c.priority, ...deadline(contract, c.days), rule: `Contract date (${short(contract)}) + ${c.days} days, set by ${label}` }));
  if (r.closingDate) targets.push({ key: 'closing', name: existing.closing ? existing.closing.name : NAMES.closing, priority: 1, ...deadline(day(r.closingDate), 0), rule: `New closing date from ${label} (${short(day(r.closingDate))})` });

  const dealLine = `${v.dealId}, ${md(parent.name)}`;
  const assignees = (parent.assignees || []).map((a) => Number(a.id)).filter(Number.isInteger);
  const ops = [];
  for (const t of targets) {
    const ex = existing[t.key];
    if (!ex) {
      ops.push({ op: 'create', key: t.key, name: t.name, dueMs: t.dueMs, dueLabel: t.dueLabel, body: createBody(t, dealLine, assignees) });
    } else if (Number(ex.due_date) !== t.dueMs) {
      ops.push({
        op: 'update', key: t.key, name: ex.name, taskId: ex.id, url: ex.url,
        oldDue: ex.due_date ? Number(ex.due_date) : null, oldLabel: ex.due_date ? stamp(ex.due_date) : 'no date',
        dueMs: t.dueMs, dueLabel: t.dueLabel,
        body: { due_date: t.dueMs, due_date_time: true, markdown_content: describe(t, dealLine) },
      });
    }
  }
  const closingTarget = targets.find((t) => t.key === 'closing');
  if (closingTarget && Number(parent.due_date) !== closingTarget.dueMs) {
    ops.push({
      op: 'update', isParent: true, key: 'deal', name: parent.name, taskId: parent.id, url: parent.url,
      oldDue: parent.due_date ? Number(parent.due_date) : null, oldLabel: parent.due_date ? stamp(parent.due_date) : 'no date',
      dueMs: closingTarget.dueMs, dueLabel: closingTarget.dueLabel, body: { due_date: closingTarget.dueMs, due_date_time: true },
    });
  }
  // Check every milestone, changed or not, against the closing date that will apply after this amendment.
  const effective = Object.values(existing).map((t) => ({ key: fieldValue(t, KEY_FIELD), name: t.name, dueMs: Number(t.due_date), dueLabel: stamp(t.due_date) }));
  for (const t of targets) {
    const i = effective.findIndex((e) => e.key === t.key);
    if (i >= 0) effective[i] = t; else effective.push(t);
  }
  const closingMs = closingTarget ? closingTarget.dueMs : Number((existing.closing || parent).due_date);
  if (closingMs) warnings.push(...afterClosing(effective, closingMs));
  const changes = ops.map((o) => ({
    key: o.key, name: o.isParent ? 'Deal task due date' : o.name, action: o.op === 'create' ? 'added' : 'moved', from: o.oldLabel || null, to: o.dueLabel,
  }));
  out = {
    route: ops.length ? 'write' : 'unchanged', status: ops.length ? 'updated' : 'unchanged', parent: parentInfo, ops, changes, warnings,
    commentIntro: `Deadlines changed by ${label}.`, note: r.note,
  };
  if (!ops.length) {
    out.httpStatus = 200;
    out.response = {
      ok: true, status: 'unchanged', deal_id: v.dealId, task_id: parent.id, task_url: parent.url, warnings,
      message: 'Every deadline already matches this amendment, so nothing was changed.',
    };
  }
}

return [{ json: { event: v.event, dealId: v.dealId, ...out } }];

// One item per ClickUp write. The loop after this node sends them one at a time, so a retry
// only ever repeats the call that failed (a node that holds several items retries all of them).
const plan = $('Plan Changes').first().json;
let parent = plan.parent;
if ($('ClickUp: Create Deal Task').isExecuted) {
  const t = $('ClickUp: Create Deal Task').first().json;
  parent = { id: t.id, name: t.name, url: t.url };
}
return plan.ops.map((op) => ({
  json: {
    ...op,
    parentId: parent.id,
    parentName: parent.name,
    parentUrl: parent.url,
    body: op.op === 'create' ? { ...op.body, parent: parent.id } : op.body,
  },
  pairedItem: { item: 0 },
}));

// Runs once per write, after success or failure, and records the result for the summary.
const op = $('Loop: ClickUp Writes').item.json;
const res = $json;
const ok = !res.error && typeof res.id === 'string' && res.id.length > 0;
let error = '';
if (!ok) {
  const e = res.error;
  error = e && typeof e === 'object' ? String(e.message || e.description || 'unknown error') : String(e || 'ClickUp did not return a task');
}
return {
  json: {
    op: op.op,
    key: op.key,
    name: op.name,
    isParent: Boolean(op.isParent),
    ok,
    taskId: ok ? res.id : op.taskId || null,
    url: ok ? res.url || op.url || null : op.url || null,
    oldDue: op.oldDue === undefined ? null : op.oldDue,
    oldLabel: op.oldLabel || '',
    dueMs: op.dueMs,
    dueLabel: op.dueLabel,
    parentId: op.parentId,
    parentName: op.parentName,
    parentUrl: op.parentUrl,
    error,
  },
};

// Collects the results of every write and, for amendments, writes the comment text.
// Reached from the loop when it is done, or straight from "ClickUp: Create Deal Task" when that call failed.
const plan = $('Plan Changes').first().json;
const looped = $('Loop: ClickUp Writes').isExecuted;
const results = looped ? $input.all().map((i) => i.json) : [];
let parentError = '';
let parent = plan.parent;
if (!looped) {
  const e = $input.first().json.error;
  parentError = e && typeof e === 'object' ? String(e.message || e.description || 'unknown error') : String(e || 'unknown error');
} else if (results.length) {
  parent = { id: results[0].parentId, name: results[0].parentName, url: results[0].parentUrl };
}
const failed = results.filter((r) => !r.ok);
const applied = results.filter((r) => r.ok && !r.isParent);

let comment = '';
if (plan.event === 'amendment' && applied.length) {
  const lines = applied.map((r) => (r.op === 'update' ? `${r.name}: moved from ${r.oldLabel} to ${r.dueLabel}` : `${r.name}: added, due ${r.dueLabel}`));
  comment = [plan.commentIntro, ...(plan.note ? [`Note from the sender: ${plan.note}`] : []), '', ...lines].join('\n');
  if (plan.warnings.length) comment += '\n\nPlease check:\n' + plan.warnings.join('\n');
  if (failed.length) comment += '\n\nNot changed yet because ClickUp returned an error: ' + failed.map((f) => f.name).join(', ') + '. Resend the amendment to retry.';
}

return [{
  json: {
    event: plan.event,
    dealId: plan.dealId,
    status: plan.status,
    warnings: plan.warnings,
    milestones: plan.milestones || [],
    changes: plan.changes || [],
    parent,
    parentError,
    results,
    failed,
    comment,
    needsComment: comment !== '',
  },
}];

// Builds the answer for the sender and decides whether this run should raise an alert.
const s = $('Summarize Writes').first().json;
let commentError = '';
if ($('ClickUp: Add Comment').isExecuted) {
  const c = $json;
  if (c.error || c.id === undefined) {
    commentError = c.error && typeof c.error === 'object' ? String(c.error.message || 'unknown error') : 'ClickUp did not return a comment ID';
  }
}
const byKey = Object.fromEntries(s.results.filter((r) => !r.isParent).map((r) => [r.key, r]));
const failedList = s.failed.map((f) => ({ key: f.key, name: f.name, error: f.error }));
let httpStatus = 200;
let failed = false;
let errorMessage = '';
let status = s.status;

if (s.parentError) {
  httpStatus = 502; failed = true; status = 'failed';
  errorMessage = `Could not create the deal task for ${s.dealId} in ClickUp: ${s.parentError}. Nothing was created. Resend the webhook to retry.`;
} else if (s.failed.length) {
  httpStatus = 502; failed = true; status = 'partial';
  errorMessage = `${s.failed.length} of ${s.results.length} ClickUp changes failed for deal ${s.dealId}: `
    + s.failed.map((f) => `${f.name} (${f.error})`).join('; ')
    + '. Resend the same webhook to retry. Changes that already went through are not repeated.';
} else if (commentError) {
  failed = true;
  errorMessage = `Deadlines for deal ${s.dealId} were updated, but the ClickUp comment could not be added (${commentError}). Please add it by hand:\n${s.comment}`;
}

const response = {
  ok: !s.parentError && !s.failed.length,
  status,
  deal_id: s.dealId,
  task_id: s.parent ? s.parent.id : null,
  task_url: s.parent ? s.parent.url : null,
};
if (s.event === 'under_contract') {
  response.milestones = s.milestones.map((m) => {
    const w = byKey[m.key];
    return { ...m, task_id: w && w.ok ? w.taskId : m.task_id, task_url: w && w.ok ? w.url : m.task_url, created: Boolean(w && w.ok) };
  });
} else {
  const done = new Set(s.results.filter((r) => r.ok).map((r) => r.key));
  response.changes = s.changes.filter((c) => done.has(c.key));
  response.comment_added = s.needsComment && !commentError;
}
response.failed = failedList;
response.warnings = s.warnings;

return [{ json: { httpStatus, failed, errorMessage, response } }];

// Checks the digest settings, then sets the window: open milestones that are overdue,
// or due between now and the end of the day DIGEST_DAYS from now.
// Settings problems do not throw: they go to "Respond: Digest Not Set Up", so Run Now gets a clear 500.
const TZ = $env.TIMEZONE || 'America/New_York';
const problems = [];
const required = {
  CLICKUP_API_TOKEN: $env.CLICKUP_API_TOKEN,
  CLICKUP_LIST_ID: $env.CLICKUP_LIST_ID,
  CLICKUP_DEAL_ID_FIELD_ID: $env.CLICKUP_DEAL_ID_FIELD_ID,
  CLICKUP_MILESTONE_FIELD_ID: $env.CLICKUP_MILESTONE_FIELD_ID,
};
for (const [name, value] of Object.entries(required)) if (!value) problems.push(`${name} is not set`);
const now = DateTime.now().setZone(TZ);
if (!now.isValid) problems.push(`TIMEZONE "${TZ}" is not a valid IANA time zone, for example America/Chicago`);

const whole = (name, value, fallback, max) => {
  if (value === undefined || value === null || String(value).trim() === '') return fallback;
  const n = Number(String(value).trim());
  if (!Number.isInteger(n) || n < 0 || n > max) {
    problems.push(`${name} must be a whole number from 0 to ${max}`);
    return fallback;
  }
  return n;
};
const digestDays = whole('DIGEST_DAYS', $env.DIGEST_DAYS, 7, 60);
const lookback = whole('DIGEST_OVERDUE_DAYS', $env.DIGEST_OVERDUE_DAYS, 60, 365);

const isEmail = (v) => typeof v === 'string' && /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(v.trim());
let team = [];
try {
  team = JSON.parse($env.TEAM_MEMBERS || '[]');
  if (!Array.isArray(team) || !team.length || team.some((m) => !m || !isEmail(m.email) || !Number.isInteger(Number(m.clickup_id)))) throw new Error('bad');
} catch (e) {
  problems.push('TEAM_MEMBERS must be a JSON list of at least one person, each with an email and a numeric clickup_id');
  team = [];
}

const channels = [...new Set(String($env.DIGEST_CHANNELS || 'slack,email').toLowerCase().split(',').map((s) => s.trim()).filter(Boolean))];
const unknown = channels.filter((c) => !['slack', 'email'].includes(c));
if (unknown.length) problems.push(`DIGEST_CHANNELS can only list slack and email, not ${unknown.join(', ')}`);
if (!channels.some((c) => ['slack', 'email'].includes(c))) problems.push('DIGEST_CHANNELS must be slack, email or slack,email');
if (channels.includes('slack') && !$env.SLACK_BOT_TOKEN) problems.push('DIGEST_CHANNELS includes slack, but SLACK_BOT_TOKEN is not set');
if (channels.includes('email') && !$env.EMAIL_API_KEY) problems.push('DIGEST_CHANNELS includes email, but EMAIL_API_KEY is not set');
if (channels.includes('email') && !$env.EMAIL_FROM) problems.push('DIGEST_CHANNELS includes email, but EMAIL_FROM is not set');

const runNow = $('Webhook: Run Now').isExecuted;
const trigger = runNow ? 'run_now' : 'schedule';
if (problems.length) {
  const errors = problems.map((p) => 'Workflow setting: ' + p);
  return [{
    json: {
      ok: false, trigger, httpStatus: 500, errors,
      errorMessage: `The deal digest is not set up, so nothing was sent. ${problems.join('; ')}.`,
      response: { ok: false, trigger, errors },
    },
  }];
}

const body = runNow ? $('Webhook: Run Now').first().json.body : null;
return [{
  json: {
    ok: true,
    trigger,
    force: Boolean(body && body.force === true),
    timezone: TZ,
    team,
    channels: channels.filter((c) => ['slack', 'email'].includes(c)),
    now: now.toMillis(),
    today: now.toISODate(),
    todayLabel: now.toFormat('cccc, LLL d, yyyy'),
    digestDays,
    // ClickUp's due_date_gt and due_date_lt filters are strict, so the edges are moved by 1 ms.
    dueAfter: now.minus({ days: lookback }).startOf('day').toMillis() - 1,
    dueBefore: now.plus({ days: digestDays }).endOf('day').toMillis() + 1,
  },
}];

// Groups the open milestones by person and then by deal, and builds one Slack message and one email per person.
// A digest that already went out today with the same content is skipped, so a second run never repeats it.
const w = $('Digest Window').first().json;
const TZ = w.timezone;
const DEAL_FIELD = $env.CLICKUP_DEAL_ID_FIELD_ID;
const KEY_FIELD = $env.CLICKUP_MILESTONE_FIELD_ID;
// "Digest Window" already checked the team list and the channels, so they are read from it.
const team = w.team;
const slackOn = w.channels.includes('slack');
const emailOn = w.channels.includes('email');
const emailFrom = $env.EMAIL_FROM || '';

const store = $getWorkflowStaticData('global');
if (!store.digests || typeof store.digests !== 'object') store.digests = {};
const keepFrom = DateTime.fromMillis(w.now, { zone: TZ }).minus({ days: 7 }).toISODate();
for (const k of Object.keys(store.digests)) if (k.slice(0, 10) < keepFrom) delete store.digests[k];

const fieldValue = (t, id) => {
  const f = (t.custom_fields || []).find((x) => x.id === id);
  return f && f.value !== undefined && f.value !== null ? String(f.value) : '';
};
const slackEscape = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const htmlEscape = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const safeUrl = (u) => (typeof u === 'string' && /^https:\/\/[^\s"'<>|]+$/.test(u) ? u : '');
const hash = (s) => {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(16).padStart(8, '0');
};
const today = DateTime.fromMillis(w.now, { zone: TZ }).startOf('day');
const when = (ms) => {
  const d = DateTime.fromMillis(ms, { zone: TZ });
  const diff = Math.round(d.startOf('day').diff(today, 'days').days);
  let rel;
  if (ms < w.now) rel = diff === 0 ? 'overdue, was due today' : `${-diff} day${diff === -1 ? '' : 's'} overdue`;
  else rel = diff === 0 ? 'due today' : diff === 1 ? 'due tomorrow' : `due in ${diff} days`;
  return { label: d.toFormat('ccc LLL d, h:mm a'), rel };
};

// Deal names come from the parent tasks (second query); milestones from the first, paged query.
const deals = new Map();
for (const page of $input.all()) for (const t of page.json.tasks || []) if (!t.parent) deals.set(t.id, t);
const seen = new Set();
const items = [];
for (const page of $('ClickUp: Get Due Milestones').all()) {
  for (const t of page.json.tasks || []) {
    if (seen.has(t.id)) continue;
    seen.add(t.id);
    const key = fieldValue(t, KEY_FIELD);
    const dealId = fieldValue(t, DEAL_FIELD);
    if (!key || !dealId || !t.due_date || !t.parent) continue;
    if (t.status && ['closed', 'done'].includes(t.status.type)) continue;
    const due = Number(t.due_date);
    if (!(due > w.dueAfter && due < w.dueBefore)) continue;
    const parent = deals.get(t.parent);
    items.push({
      id: t.id, name: t.name, url: safeUrl(t.url), due, overdue: due < w.now, dealId,
      dealTitle: parent ? parent.name : `Deal ${dealId}`, dealUrl: parent ? safeUrl(parent.url) : '',
      assignees: (t.assignees || []).map((a) => String(a.id)),
    });
  }
}

const known = new Set(team.map((m) => String(m.clickup_id)));
const notInTeam = [...new Set(items.flatMap((i) => i.assignees).filter((a) => !known.has(a)))];
const messages = [];
const skipped = [];
const people = [];
for (const member of team) {
  const id = String(member.clickup_id);
  const mine = items.filter((i) => i.assignees.includes(id)).sort((a, b) => a.due - b.due || a.name.localeCompare(b.name));
  if (!mine.length) continue;
  const groups = [];
  for (const i of mine) {
    let g = groups.find((x) => x.dealId === i.dealId);
    if (!g) { g = { dealId: i.dealId, title: i.dealTitle, url: i.dealUrl, items: [] }; groups.push(g); }
    g.items.push(i);
  }
  const overdue = mine.filter((i) => i.overdue).length;
  const soon = mine.length - overdue;
  const name = member.name || member.email;
  const summary = `${overdue} overdue, ${soon} due in the next ${w.digestDays} days`;
  people.push({ member: name, overdue, due_soon: soon });

  const slack = [`*Deal deadlines for ${slackEscape(name)}*, ${w.todayLabel}`, `${summary}.`];
  const html = [`<p><strong>Deal deadlines for ${htmlEscape(name)}</strong>, ${htmlEscape(w.todayLabel)}</p>`, `<p>${htmlEscape(summary)}.</p>`];
  const text = [`Deal deadlines for ${name}, ${w.todayLabel}`, `${summary}.`];
  for (const g of groups) {
    const title = g.url ? `<${g.url}|${slackEscape(g.title)}>` : slackEscape(g.title);
    slack.push('', `*${title}* (${slackEscape(g.dealId)})`);
    html.push(`<h3 style="margin:16px 0 4px">${g.url ? `<a href="${htmlEscape(g.url)}">${htmlEscape(g.title)}</a>` : htmlEscape(g.title)} (${htmlEscape(g.dealId)})</h3>`, '<ul>');
    text.push('', `${g.title} (${g.dealId})`);
    for (const i of g.items) {
      const t = when(i.due);
      const flag = i.overdue ? 'OVERDUE ' : '';
      slack.push(`• ${i.overdue ? '*OVERDUE* ' : ''}${i.url ? `<${i.url}|${slackEscape(i.name)}>` : slackEscape(i.name)}: ${t.label}, ${t.rel}`);
      html.push(`<li>${i.overdue ? '<strong style="color:#b42318">OVERDUE</strong> ' : ''}${i.url ? `<a href="${htmlEscape(i.url)}">${htmlEscape(i.name)}</a>` : htmlEscape(i.name)}: ${htmlEscape(t.label)}, ${htmlEscape(t.rel)}</li>`);
      text.push(`* ${flag}${i.name}: ${t.label}, ${t.rel}${i.url ? ' ' + i.url : ''}`);
    }
    html.push('</ul>');
  }
  html.push('<p style="color:#667085;font-size:12px">Sent by the deal deadline workflow. Update or complete the tasks in ClickUp.</p>');
  const content = { slack: slack.join('\n'), email: html.join('\n') };
  const subject = `Deal deadlines: ${overdue} overdue, ${soon} due soon (${today.toFormat('ccc LLL d')})`;

  const want = [];
  if (slackOn && member.slack_id) want.push('slack');
  if (emailOn && member.email) want.push('email');
  if (!want.length) skipped.push({ member: name, channel: null, reason: 'no delivery channel is set up for this person' });
  for (const channel of want) {
    const h = hash(content[channel]);
    const dedupeKey = `${w.today}|${id}|${channel}`;
    if (!w.force && store.digests[dedupeKey] === h) {
      skipped.push({ member: name, channel, reason: 'already sent today with the same content' });
      continue;
    }
    messages.push({
      channel, member: name, memberId: id, dedupeKey, hash: h, overdue, dueSoon: soon,
      slackBody: channel === 'slack' ? { channel: String(member.slack_id), text: content.slack, unfurl_links: false, unfurl_media: false } : null,
      emailBody: channel === 'email' ? { from: emailFrom, to: [String(member.email)], subject, html: content.email, text: text.join('\n') } : null,
      // Resend keeps an idempotency key for 24 hours, so a retried request can never send the same email twice.
      idempotencyKey: `deal-digest-${w.today}-${id}-${h}${w.force ? '-f' + w.now : ''}`,
    });
  }
}

const stats = { trigger: w.trigger, date: w.today, milestones: items.length, people, skipped, not_in_team: notInTeam };
if (!messages.length) {
  return [{ json: { nothing: true, stats, response: { ok: true, ...stats, sent: [], failed: [] } }, pairedItem: { item: 0 } }];
}
return messages.map((m) => ({ json: { ...m, stats }, pairedItem: { item: 0 } }));

// Runs once per message. Slack answers 200 even when it refuses a message ({"ok": false}), so "ok" is checked here.
const m = $('Loop: Send Digests').item.json;
const r = $json;
let ok = false;
let error = '';
if (m.channel === 'slack') {
  ok = r.ok === true;
  if (!ok) error = typeof r.error === 'string' ? `Slack said ${r.error}` : String((r.error && r.error.message) || 'no answer from Slack');
} else {
  ok = !r.error && typeof r.id === 'string' && r.id.length > 0;
  if (!ok) error = String((r.error && (r.error.message || r.error)) || 'the email API returned no message ID');
}
if (ok) {
  const store = $getWorkflowStaticData('global');
  if (!store.digests || typeof store.digests !== 'object') store.digests = {};
  store.digests[m.dedupeKey] = m.hash;
}
return { json: { channel: m.channel, member: m.member, ok, error } };

// Sums up the run for the Run Now caller and decides whether to raise an alert.
const stats = $('Build Digests').first().json.stats;
const results = $input.all().map((i) => i.json);
const failed = results.filter((r) => !r.ok);
const errorMessage = failed.length
  ? `Deal digest: ${failed.length} of ${results.length} messages failed: `
    + failed.map((f) => `${f.member} by ${f.channel} (${f.error})`).join('; ')
    + '. The others were sent. Run it again to retry; people who already got the same digest today are skipped.'
  : '';
return [{
  json: {
    failed: failed.length > 0,
    httpStatus: failed.length ? 502 : 200,
    errorMessage,
    response: {
      ok: failed.length === 0,
      ...stats,
      sent: results.filter((r) => r.ok).map((r) => ({ member: r.member, channel: r.channel })),
      failed: failed.map((r) => ({ member: r.member, channel: r.channel, error: r.error })),
    },
  },
}];
